-- Fantasy suggested prices reweighted for how often each player turns up.
-- Attendance is PC 8 and 9 played (out of 2) or PC 1 to 7 cashes (out of 5),
-- whichever is higher. Price = 4 + (ability price - 4) x (0.6 + 0.4 x attendance),
-- so a regular keeps his price and someone who rarely plays is cheaper but riskier.
update public.fantasy_prices f set suggested = s.value::numeric
  from jsonb_each_text('{"Lewis Forrest":9.0,"Luke Davies":10.0,"Mikey Guinness":12.0,"Oli Graham":9.0,"Dan Wells":11.5,"Matt Watts":9.0,"Adam Khalil":8.0,"Luke Egan":10.5,"Joel Keaney":9.0,"Matt Duke":7.5,"Max Halder":9.5,"Barney Chaudhry":9.0,"Liam English":9.0,"Ben O''Callaghan":8.5,"Jack Warby":6.5,"Joseph D''Ambrosio":8.0,"Dan Buckley":7.5,"Rory Peach":8.0,"James Lauer":8.0,"James Beer":6.0,"Cian Hughes":7.5,"Dan Campbell":7.5,"Tom Sibley":6.5,"Evan Buxton":7.0,"Iwan James":7.0,"Ed Browne":7.0,"Alfie Mortimer":7.0,"Sam Tookey":6.5,"Aidan Garratt":8.0,"Finley Bowden":6.5,"Aidan Wood":6.5,"James Phillips":6.0,"Adam Butcher":5.5,"Harvey Simpson":6.0,"Oli Makin":6.5,"George Burton":6.5,"Luke Lavery":6.5,"Matt Hawkins":6.0,"Danny Hartland":6.0,"Jude Cockin":5.5,"Ben Clarke":5.5,"Mike Britland":6.0,"Finley Jackson":6.0,"Leila Mitchell":5.0,"Ben Browne":5.5,"Thomas Batho":5.5,"Jack Vicars":6.0,"Jono Blatch":5.5,"Alex Vienna":5.0,"Ollie Preece":5.0,"Freddie Taylor":5.0,"James Payne":5.0,"Max Cutler":5.0,"Harvey Richards":5.0,"Archie Shelbourne":5.0,"Jack Redfern":5.0,"Jack Hawley":5.0,"Ethan Warren":5.0,"Callum Ellis":5.0,"Sam Oddy":5.0,"Ruben Parker":5.0,"Seth Cluewes":5.0,"Max Browne":5.0,"Oliver Pratt":5.0,"Lewis Collet":4.5,"Quinn Collins":4.5,"Nathan Barrow":4.5,"Tom Ainger":4.5,"Michael Davy":4.0,"Henry Gascoigne":4.0,"Oliver Shaw":4.0}'::jsonb) s
  join public.players p on p.name = s.key
 where f.player_id = p.id;
